// Improved application with security best practices and error handling
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { v4: uuidv4 } = require('uuid');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================================================
// MIDDLEWARE - Security & Error Handling
// ============================================================================

// 1. Security Headers (helmet.js)
app.use(helmet());

// 2. Request Size Limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 3. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Request Logging Middleware
app.use((req, res, next) => {
  const requestId = uuidv4();
  req.id = requestId;
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`[${req.id}] ${req.method} ${req.path} ${res.statusCode} ${duration}ms`);
  });

  next();
});

// ============================================================================
// INPUT VALIDATION UTILITIES
// ============================================================================

/**
 * Validate integer ID parameter
 * @param {string} id - The ID to validate
 * @returns {number|null} Parsed ID or null if invalid
 */
function validateId(id) {
  const parsed = parseInt(id, 10);
  if (!Number.isInteger(parsed) || parsed <= 0) {
    return null;
  }
  return parsed;
}

/**
 * Sanitize user data for output
 * Removes sensitive fields
 */
function sanitizeUser(user) {
  const { password, ...safe } = user;
  return safe;
}

// ============================================================================
// MOCK DATA
// ============================================================================

const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * No authentication required
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: NODE_ENV,
    });
  } catch (error) {
    console.error(`[${req.id}] Health check error:`, error.message);
    res.status(500).json({ status: 'error', message: 'Internal server error' });
  }
});

/**
 * Get all users
 * Security: Consider adding authentication here
 * Returns sanitized user data
 */
app.get('/users', (req, res) => {
  try {
    // Validate optional query parameters
    const skip = Math.max(0, parseInt(req.query.skip || '0', 10));
    const limit = Math.min(100, Math.max(1, parseInt(req.query.limit || '10', 10)));

    if (skip < 0 || limit < 1) {
      return res.status(400).json({
        error: 'Invalid pagination parameters',
        details: 'skip must be >= 0, limit must be between 1 and 100',
      });
    }

    const paginatedUsers = users
      .slice(skip, skip + limit)
      .map(sanitizeUser);

    res.json({
      data: paginatedUsers,
      total: users.length,
      skip,
      limit,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error(`[${req.id}] Error fetching users:`, error.message);
    res.status(500).json({
      error: 'Internal server error',
      requestId: req.id,
    });
  }
});

/**
 * Get a specific user by ID
 * Validates ID parameter
 */
app.get('/users/:id', (req, res) => {
  try {
    const userId = validateId(req.params.id);

    if (userId === null) {
      return res.status(400).json({
        error: 'Invalid user ID',
        details: 'ID must be a positive integer',
      });
    }

    const user = users.find((u) => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        userId,
      });
    }

    res.json(sanitizeUser(user));
  } catch (error) {
    console.error(`[${req.id}] Error fetching user ${req.params.id}:`, error.message);
    res.status(500).json({
      error: 'Internal server error',
      requestId: req.id,
    });
  }
});

// ============================================================================
// 404 & ERROR HANDLING
// ============================================================================

/**
 * 404 Handler - must be after all routes
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method,
  });
});

/**
 * Global Error Handler - must be last
 * Catches all synchronous and asynchronous errors
 */
app.use((err, req, res, next) => {
  const requestId = req.id || 'unknown';

  // Log the error
  console.error(`[${requestId}] Error:`, {
    message: err.message,
    stack: NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    statusCode: err.statusCode || 500,
  });

  // Determine response status
  const status = err.statusCode || err.status || 500;
  const isProductionError = status === 500 && NODE_ENV === 'production';

  res.status(status).json({
    error: err.message || 'Internal Server Error',
    requestId,
    ...(NODE_ENV === 'development' && { stack: err.stack }),
    ...(isProductionError && { message: 'An unexpected error occurred' }),
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (environment: ${NODE_ENV})`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

module.exports = app;

# Security Review: app.js

## Executive Summary

The original `app.js` has **critical security and reliability issues** that should be addressed before production use:

- ❌ No error handling
- ❌ No input validation
- ❌ No security headers
- ❌ No rate limiting
- ❌ No request logging
- ❌ Public exposure of user data

---

## 🔴 CRITICAL ISSUES

### 1. **Missing Error Handling**

**Problem:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Risks:**
- Server crashes silently on port conflicts
- No graceful shutdown handling
- Unhandled promise rejections crash the app
- Unhandled exceptions in route handlers aren't caught

**Fix:**
```javascript
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle shutdowns gracefully
process.on('SIGTERM', () => {
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Global error handler (must be last middleware)
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({ error: 'Internal server error' });
});
```

---

### 2. **No Input Validation**

**Problem:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // Accepts any request without validation
});
```

**Risks:**
- Query injection attacks
- Malformed requests cause crashes
- No type checking on parameters
- Pagination parameters could cause DoS

**Fix:**
```javascript
app.get('/users', (req, res) => {
  // Validate optional query parameters
  const skip = Math.max(0, parseInt(req.query.skip || '0', 10));
  const limit = Math.min(100, Math.max(1, parseInt(req.query.limit || '10', 10)));

  if (isNaN(skip) || isNaN(limit)) {
    return res.status(400).json({
      error: 'Invalid pagination parameters',
      details: 'skip and limit must be valid integers'
    });
  }

  const paginatedUsers = users.slice(skip, skip + limit);
  res.json({
    data: paginatedUsers,
    total: users.length
  });
});
```

**Additional validation tools:**
- Use `express-validator` or `joi` for robust validation
- Validate all user inputs from `req.params`, `req.query`, and `req.body`
- Whitelist acceptable values when possible

---

### 3. **Missing Security Headers**

**Problem:**
```javascript
const app = express(); // No security middleware
```

**Risks:**
- No protection against XSS attacks
- No clickjacking protection
- No MIME type sniffing protection
- Missing CORS configuration

**Fix:**
```javascript
const helmet = require('helmet');

// Add security headers
app.use(helmet());

// Optionally configure CORS
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true
}));
```

---

### 4. **Hardcoded Port & No Environment Configuration**

**Problem:**
```javascript
app.listen(3000, () => { ... });
```

**Risks:**
- Port conflicts in different environments
- Configuration not flexible for deployment
- Security settings hardcoded

**Fix:**
```javascript
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV})`);
});
```

---

### 5. **Public User Data Exposure**

**Problem:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Risks:**
- Email addresses publicly accessible to anyone
- No authentication check
- Email harvesting for spam/phishing
- GDPR/privacy violations

**Fix:**
```javascript
// 1. Add authentication middleware
app.get('/users', authenticateUser, (req, res) => {
  res.json(sanitizeUsers(users));
});

// 2. Sanitize sensitive data
function sanitizeUser(user) {
  const { password, ssn, ...safe } = user;
  return safe;
}
```

---

## 🟡 IMPORTANT RECOMMENDATIONS

### 6. **No Rate Limiting**

**Problem:** Any client can hammer the API

**Risk:** DoS attacks, resource exhaustion

**Fix:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP'
});

app.use(limiter);
```

---

### 7. **No Request Logging**

**Problem:** No audit trail for debugging or security

**Risk:** Can't investigate issues, no security monitoring

**Fix:**
```javascript
app.use((req, res, next) => {
  const requestId = require('uuid').v4();
  req.id = requestId;
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(
      `[${req.id}] ${req.method} ${req.path} ${res.statusCode} ${duration}ms`
    );
  });

  next();
});
```

---

### 8. **No Request Size Limits**

**Problem:** Large payloads can crash the server

**Risk:** Memory exhaustion, DoS

**Fix:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 9. **No 404 Handler**

**Problem:** Invalid routes return no response

**Fix:**
```javascript
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});
```

---

### 10. **Missing Try-Catch in Route Handlers**

**Problem:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // What if res.json throws?
});
```

**Fix:**
```javascript
app.get('/users', (req, res) => {
  try {
    res.json([...]);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

