// Improved Express application with security best practices and error handling
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3000;

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Helmet.js - Sets security headers (X-Frame-Options, CSP, etc.)
app.use(helmet());

// CORS - Configure allowed origins
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'localhost',
  credentials: true,
  methods: ['GET', 'POST'],
  optionsSuccessStatus: 200
}));

// Rate limiting - Prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later',
  standardHeaders: true, // Return rate limit info in RateLimit-* headers
  legacyHeaders: false, // Disable X-RateLimit-* headers
});
app.use(limiter);

// ============================================================================
// REQUEST PARSING & LOGGING
// ============================================================================

// Body parser with size limits to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// HTTP request logging
app.use(morgan('combined'));

// ============================================================================
// HEALTH CHECK ENDPOINT (No sensitive data)
// ============================================================================

app.get('/health', (req, res, next) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// ============================================================================
// USERS ENDPOINT (Protected with authentication and validation)
// ============================================================================

// Mock database
const usersDB = [
  { id: 1, name: 'Alice' },
  { id: 2, name: 'Bob' },
];

// Authentication middleware - Verify JWT or API key
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  // TODO: Verify JWT token here
  // For demo purposes, accept any token. In production, use jwt.verify()
  if (token === 'demo-token') {
    next();
  } else {
    res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// Input validation middleware for query parameters
const validateUsersQuery = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be between 1 and 100'),
  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('page must be a positive integer'),
];

app.get('/users', authenticateToken, validateUsersQuery, (req, res, next) => {
  try {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Parse query parameters with defaults
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const page = Math.max(parseInt(req.query.page) || 1, 1);
    const startIndex = (page - 1) * limit;

    // Implement pagination
    const paginatedUsers = usersDB.slice(startIndex, startIndex + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: usersDB.length,
      },
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// ============================================================================
// 404 HANDLER
// ============================================================================

app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// ============================================================================
// GLOBAL ERROR HANDLER MIDDLEWARE (Must be last)
// ============================================================================

app.use((err, req, res, next) => {
  // Log error (in production, use structured logging: winston, pino, etc.)
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: err.stack,
    method: req.method,
    path: req.path,
    ip: req.ip,
  });

  // Determine status code
  const status = err.status || err.statusCode || 500;

  // Send error response (don't expose stack trace in production)
  const isProduction = process.env.NODE_ENV === 'production';
  res.status(status).json({
    error: err.message || 'Internal server error',
    ...(isProduction ? {} : { stack: err.stack }), // Debug info only in dev
  });
});

// ============================================================================
// SERVER STARTUP & GRACEFUL SHUTDOWN
// ============================================================================

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown handlers
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after 30 seconds
  setTimeout(() => {
    console.error('Forced shutdown due to timeout');
    process.exit(1);
  }, 30000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

# Security Review: app.js

## Executive Summary

The current `app.js` has **10 critical security and error-handling issues** that require immediate attention. This review provides detailed findings and recommended fixes.

---

## Critical Issues

### 1. ❌ No Security Middleware
**Severity: CRITICAL**
- **Issue**: Missing `helmet.js`, rate limiting, and CORS configuration
- **Risk**: Application vulnerable to XSS, CSRF, clickjacking, DoS attacks
- **Failure Scenario**: Attacker sends 10,000 requests/second causing server to crash; browser runs malicious scripts due to missing CSP headers
- **Fix**: 
  ```javascript
  const helmet = require('helmet');
  const rateLimit = require('express-rate-limit');

  app.use(helmet()); // Sets security headers
  const limiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100
  });
  app.use(limiter);
  ```

### 2. ❌ No Authentication/Authorization
**Severity: CRITICAL**
- **Issue**: `/users` endpoint exposes sensitive data (emails) without authentication
- **Risk**: Unauthorized access to user data; data breaches; privacy violations
- **Failure Scenario**: Anyone can curl `http://localhost:3000/users` and access all user email addresses
- **Fix**: 
  ```javascript
  const authenticateToken = (req, res, next) => {
    const token = req.headers['authorization']?.split(' ')[1];
    if (!token) return res.status(401).json({ error: 'Unauthorized' });
    // Verify JWT token
    jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
      if (err) return res.status(403).json({ error: 'Forbidden' });
      req.user = user;
      next();
    });
  };

  app.get('/users', authenticateToken, (req, res) => { ... });
  ```

### 3. ❌ Missing Input Validation
**Severity: HIGH**
- **Issue**: No validation of query parameters, path parameters, or request body
- **Risk**: Injection attacks, unexpected behavior, memory exhaustion
- **Failure Scenario**: Request `GET /users?limit=999999&page=<script>alert()</script>` causes memory exhaustion or undefined behavior
- **Fix**:
  ```javascript
  const { query, validationResult } = require('express-validator');

  app.get('/users',
    query('limit').optional().isInt({min:1, max:100}),
    query('page').optional().isInt({min:1}),
    (req, res) => {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }
      // Process validated params
    }
  );
  ```

### 4. ❌ No Error Handling
**Severity: HIGH**
- **Issue**: No try-catch blocks or global error handler
- **Risk**: Unhandled exceptions crash server; stack traces leaked to users
- **Failure Scenario**: Exception in route handler → unhandled rejection → server crashes → DoS
- **Fix**:
  ```javascript
  // Add try-catch to each route
  app.get('/health', (req, res, next) => {
    try {
      res.json({ status: 'ok' });
    } catch (error) {
      next(error);
    }
  });

  // Add global error handler at end of middleware stack
  app.use((err, req, res, next) => {
    console.error(err.stack);
    res.status(err.status || 500).json({
      error: 'Internal server error',
      ...(process.env.NODE_ENV === 'production' ? {} : { stack: err.stack })
    });
  });
  ```

### 5. ❌ Sensitive Data Exposure
**Severity: HIGH**
- **Issue**: User email addresses hardcoded and returned in API response
- **Risk**: Privacy violation; GDPR/CCPA non-compliance; data breach
- **Failure Scenario**: PII (Personally Identifiable Information) exposed publicly via API
- **Fix**:
  ```javascript
  // Only return necessary fields; move sensitive data to secure database
  app.get('/users', authenticateToken, (req, res) => {
    const users = usersDB.map(u => ({ id: u.id, name: u.name })); // Exclude emails
    res.json(users);
  });
  ```

### 6. ❌ No Graceful Shutdown
**Severity: HIGH**
- **Issue**: No handling of SIGTERM/SIGINT signals
- **Risk**: In-flight requests dropped; database connections not closed; data loss
- **Failure Scenario**: During deployment, SIGTERM sent → server dies immediately → 500 errors to clients
- **Fix**:
  ```javascript
  const server = app.listen(3000, () => {
    console.log('Server running on port 3000');
  });

  process.on('SIGTERM', () => {
    console.log('SIGTERM received. Closing server gracefully...');
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });
    // Force exit after 30 seconds
