// Secure Express application with error handling and input validation
// Security best practices implemented

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const cors = require('cors');

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// Use Helmet to set secure HTTP headers
app.use(helmet());

// Enable CORS with specific origin (configure as needed)
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// Body parser middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// ==================== REQUEST LOGGING ====================

// Simple logging middleware (consider using Morgan in production)
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ==================== ROUTES ====================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    handleError(res, error, 500);
  }
});

// Users endpoint with validation
app.get('/users', (req, res) => {
  try {
    // Validate optional query parameters
    const limit = validateLimit(req.query.limit);
    const offset = validateOffset(req.query.offset);

    // Mock user data (replace with database query)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      total: allUsers.length,
      limit,
      offset,
    });
  } catch (error) {
    handleError(res, error, 400);
  }
});

// ==================== INPUT VALIDATION ====================

/**
 * Validate limit parameter (pagination)
 * @param {string|undefined} limit
 * @returns {number} Safe limit value
 */
function validateLimit(limit) {
  const MAX_LIMIT = 100;
  const DEFAULT_LIMIT = 10;

  if (!limit) return DEFAULT_LIMIT;

  const parsed = parseInt(limit, 10);

  if (isNaN(parsed) || parsed <= 0) {
    throw new Error('Invalid limit parameter: must be a positive integer');
  }

  return Math.min(parsed, MAX_LIMIT);
}

/**
 * Validate offset parameter (pagination)
 * @param {string|undefined} offset
 * @returns {number} Safe offset value
 */
function validateOffset(offset) {
  if (!offset) return 0;

  const parsed = parseInt(offset, 10);

  if (isNaN(parsed) || parsed < 0) {
    throw new Error('Invalid offset parameter: must be a non-negative integer');
  }

  return parsed;
}

// ==================== ERROR HANDLING ====================

/**
 * Centralized error handler
 * @param {object} res - Express response object
 * @param {Error} error - Error object
 * @param {number} statusCode - HTTP status code (default: 500)
 */
function handleError(res, error, statusCode = 500) {
  console.error(`[ERROR] ${error.message}`, error.stack);

  // Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(statusCode).json({
    error: {
      message: error.message || 'Internal server error',
      ...(isDevelopment && { stack: error.stack }),
    },
  });
}

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: 'Route not found',
      path: req.path,
    },
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  handleError(res, err, err.statusCode || 500);
});

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

if (require.main === module) {
  app.listen(PORT, HOST, () => {
    console.log(`Server running on ${HOST}:${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
  });
}

module.exports = app;

