## Conclusion

The application has **good foundational security setup** but requires fixes for **2 critical vulnerabilities** (CORS + credentials leakage, IP spoofing) before production deployment. The remaining issues are also important for robustness and compliance.

**Recommendation:** Fix P0 and P1 items before merging to main. P2 and P3 can follow in a patch release.

// Secure Express application with error handling and input validation
// Security best practices implemented - PRODUCTION READY VERSION

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const cors = require('cors');

const app = express();

// ==================== CONFIGURATION VALIDATION ====================

/**
 * Validate and parse PORT environment variable
 * Throws if PORT is invalid (non-numeric, out of range)
 */
function getPort() {
  const portStr = process.env.PORT || '3000';
  const port = parseInt(portStr, 10);

  if (isNaN(port) || port < 1 || port > 65535) {
    throw new Error(
      `Invalid PORT: "${portStr}" is not a valid port number (must be 1-65535)`
    );
  }

  return port;
}

/**
 * Validate HOST environment variable
 * Rejects shell metacharacters and invalid hostnames
 */
function getHost() {
  const host = process.env.HOST || 'localhost';

  // Basic validation: only alphanumeric, dots, hyphens, colons
  if (!/^[a-zA-Z0-9.\-:]+$/.test(host)) {
    throw new Error(
      `Invalid HOST: "${host}" contains invalid characters`
    );
  }

  return host;
}

/**
 * Validate and normalize CORS origins from environment
 * Validates URL format and rejects wildcards when credentials are enabled
 */
function getCorsOrigins() {
  const originStr = process.env.ALLOWED_ORIGINS || 'http://localhost:3000';

  const origins = originStr
    .split(',')
    .map(origin => origin.trim())
    .filter(origin => {
      if (!origin.length) return false;

      // Validate URL format
      try {
        new URL(origin);

        // Reject wildcard origins when credentials are enabled
        if (origin === '*' || origin === '*:*') {
          console.warn('WARNING: Wildcard origin (*) rejected. Cannot use wildcards with credentials: true');
          return false;
        }

        return true;
      } catch (err) {
        console.warn(`Invalid CORS origin: "${origin}" - ${err.message}`);
        return false;
      }
    });

  if (origins.length === 0) {
    console.warn('No valid CORS origins configured. Using default: http://localhost:3000');
    return ['http://localhost:3000'];
  }

  return origins;
}

// ==================== SECURITY MIDDLEWARE ====================

// Configure proxy trust based on deployment environment
// Must be set BEFORE rate limiter and logging (uses req.ip)
if (process.env.BEHIND_PROXY === 'true') {
  const trustCount = parseInt(process.env.PROXY_TRUST_COUNT || '1', 10);
  if (trustCount >= 1 && trustCount <= 10) {
    app.set('trust proxy', trustCount);
    console.log(`Trusting ${trustCount} proxy hops for X-Forwarded-For header`);
  } else {
    console.warn('Invalid PROXY_TRUST_COUNT; defaulting to 1');
    app.set('trust proxy', 1);
  }
} else {
  app.set('trust proxy', false);
  console.log('Proxy trust disabled - X-Forwarded-For headers will be ignored');
}

// Use Helmet to set secure HTTP headers
app.use(helmet());

// Enable HTTPS redirect (recommend setting FORCE_HTTPS=true in production)
if (process.env.FORCE_HTTPS === 'true') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(301, `https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// Enable CORS with validated origins and origin-check function
const corsOrigins = getCorsOrigins();
const validateCorsOrigin = (origin, callback) => {
  // Allow requests with no origin (like mobile apps, curl requests)
  if (!origin) return callback(null, true);

  // Check if origin is in whitelist
  if (corsOrigins.includes(origin)) {
    callback(null, true);
  } else {
    callback(new Error('Not allowed by CORS'));
  }
};

app.use(cors({
  origin: validateCorsOrigin,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'],
