// ==================== INPUT VALIDATION ====================

/**
 * Validate limit parameter (pagination)
 * @param {string|undefined} limit
 * @returns {number} Safe limit value
 * @throws {Error} If limit is invalid
 */
function validateLimit(limit) {
  const MAX_LIMIT = 100;
  const DEFAULT_LIMIT = 10;

  if (!limit) return DEFAULT_LIMIT;

  const parsed = parseInt(limit, 10);

  if (isNaN(parsed) || parsed <= 0) {
    throw new Error('Invalid limit parameter: must be a positive integer');
  }

  return Math.min(parsed, MAX_LIMIT);
}

/**
 * Validate offset parameter (pagination)
 * @param {string|undefined} offset
 * @returns {number} Safe offset value
 * @throws {Error} If offset is invalid
 */
function validateOffset(offset) {
  if (!offset) return 0;

  const parsed = parseInt(offset, 10);

  if (isNaN(parsed) || parsed < 0) {
    throw new Error('Invalid offset parameter: must be a non-negative integer');
  }

  return parsed;
}

// ==================== ERROR HANDLING ====================

/**
 * Centralized error handler
 * @param {object} res - Express response object
 * @param {Error} error - Error object
 * @param {number} statusCode - HTTP status code (default: 500)
 * @param {string} errorId - Unique error identifier for tracking
 */
function handleError(res, error, statusCode = 500, errorId) {
  const isDevelopment = process.env.NODE_ENV !== 'production';

  console.error(JSON.stringify({
    timestamp: new Date().toISOString(),
    errorId: errorId || 'unknown',
    statusCode,
    message: error.message,
    stack: isDevelopment ? error.stack : undefined,
  }));

  // Don't expose stack traces or sensitive info in production
  res.status(statusCode).json({
    error: {
      id: errorId,
      message: error.message || 'Internal server error',
      ...(isDevelopment && { stack: error.stack }),
    },
  });
}

// 404 handler - sanitize path before echoing, handle HEAD requests
app.use((req, res) => {
  if (req.method === 'HEAD') {
    // HEAD requests must not have a body
    res.status(404).end();
  } else {
    // Don't echo req.path to avoid reflected XSS; just return generic message
    res.status(404).json({
      error: {
        message: 'Route not found',
      },
    });
  }
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  const errorId = require('crypto').randomUUID?.() || `err-${Date.now()}`;
  handleError(res, err, err.statusCode || 500, errorId);
});

