// Improved Express application with security best practices
// Includes: error handling, input validation, security headers, rate limiting

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting middleware - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all routes
app.use(limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// ============================================
// INPUT VALIDATION UTILITIES
// ============================================

const validateUserId = (id) => {
  if (!id) return false;
  const parsed = parseInt(id, 10);
  return !isNaN(parsed) && parsed > 0;
};

const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return email && emailRegex.test(email);
};

// ============================================
// ROUTES
// ============================================

app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Health check failed',
    });
  }
});

app.get('/users', (req, res, next) => {
  try {
    // Input validation for query parameters
    const { id, limit, offset } = req.query;

    // Validate optional ID filter
    if (id && !validateUserId(id)) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid user ID format',
        code: 'INVALID_USER_ID',
      });
    }

    // Validate pagination parameters
    let parsedLimit = 10; // Default
    let parsedOffset = 0; // Default

    if (limit) {
      parsedLimit = parseInt(limit, 10);
      if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
        return res.status(400).json({
          status: 'error',
          message: 'Invalid limit. Must be between 1 and 100.',
          code: 'INVALID_LIMIT',
        });
      }
    }

    if (offset) {
      parsedOffset = parseInt(offset, 10);
      if (isNaN(parsedOffset) || parsedOffset < 0) {
        return res.status(400).json({
          status: 'error',
          message: 'Invalid offset. Must be non-negative.',
          code: 'INVALID_OFFSET',
        });
      }
    }

    // Mock data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by ID if provided
    let filteredUsers = allUsers;
    if (id) {
      const userId = parseInt(id, 10);
      filteredUsers = allUsers.filter((user) => user.id === userId);
      if (filteredUsers.length === 0) {
        return res.status(404).json({
          status: 'error',
          message: 'User not found',
          code: 'USER_NOT_FOUND',
        });
      }
    }

    // Apply pagination
    const users = filteredUsers.slice(parsedOffset, parsedOffset + parsedLimit);

    res.status(200).json({
      status: 'success',
      data: users,
      pagination: {
        limit: parsedLimit,
        offset: parsedOffset,
        total: filteredUsers.length,
      },
    });
  } catch (error) {
    next(error);
  }
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// 404 Not Found handler
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
    code: 'NOT_FOUND',
    path: req.path,
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  // Log error (in production, use proper logging service)
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Determine status code
  const statusCode = err.status || err.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Send error response
  res.status(statusCode).json({
    status: 'error',
    message: err.message || 'Internal server error',
    code: err.code || 'INTERNAL_SERVER_ERROR',
    ...(isDevelopment && { stack: err.stack }), // Only in development
  });
});

// ============================================
// SERVER STARTUP & GRACEFUL SHUTDOWN
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
const gracefulShutdown = () => {
  console.log('Received shutdown signal. Closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown due to timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

