const http = require('http');
const url = require('url');

function express() {
  const routes = {};
  const middlewares = [];

  function app(req, res) {
    const pathname = url.parse(req.url).pathname;
    const method = req.method.toLowerCase();
    const key = `${method}:${pathname}`;

    if (routes[key]) {
      const handler = routes[key];
      // NO ERROR HANDLING - if handler throws, it will crash
      try {
        handler(req, res);
      } catch (err) {
        // Handler may not be properly awaited or have error handling
        console.error('Unhandled error in route handler:', err);
        // This doesn't properly handle async errors!
      }
    } else {
      res.statusCode = 404;
      res.end('Not Found');
    }
  }

  app.get = function(path, handler) {
    routes[`get:${path}`] = handler;
    return app;
  };

  app.listen = function(port, callback) {
    const server = http.createServer(app);
    server.listen(port, callback);
    return server;
  };

  app.set = function(key, value) {
    app[`_${key}`] = value;
    return app;
  };

  app.get = function(key) {
    return app[`_${key}`];
  };

  // Add json method to response
  if (!http.ServerResponse.prototype.json) {
    http.ServerResponse.prototype.json = function(data) {
      this.setHeader('Content-Type', 'application/json');
      this.end(JSON.stringify(data));
    };
  }

  if (!http.ServerResponse.prototype.send) {
    http.ServerResponse.prototype.send = function(data) {
      this.setHeader('Content-Type', 'text/html');
      this.end(data);
    };
  }

  return app;
}

module.exports = express;

