// Improved application with security best practices
// - Error handling
// - Input validation
// - Security headers
// - Rate limiting
// - Authentication/Authorization
// - CORS configuration
// - Environment-based configuration

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. HTTP Security Headers (Helmet)
app.use(helmet());

// 2. CORS Configuration
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// 3. Request Logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// 4. Request Parsing
app.use(express.json({ limit: '1kb' })); // Limit payload size
app.use(express.urlencoded({ extended: false, limit: '1kb' }));

// 5. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  skipSuccessfulRequests: true, // Only count failed requests
});

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * GET /health
 * Returns server status and timestamp
 */
app.get('/health', (req, res) => {
  try {
    // Validate query parameters to prevent injection
    const allowedParams = new Set(['format']);
    for (const param of Object.keys(req.query)) {
      if (!allowedParams.has(param)) {
        return res.status(400).json({ error: 'Invalid query parameter: ' + param });
      }
    }

    res.json({
