 * 2. Require authorization (only return own data or admin privilege)
 * 3. Implement pagination and filtering
 * 4. Use database queries with prepared statements
 */
app.get('/users', strictLimiter, authenticateRequest, (req, res) => {
  try {
    // Input validation: Check for malicious query params
    const page = parseInt(req.query.page, 10) || 1;
    const limit = parseInt(req.query.limit, 10) || 10;

