# app.js Improvements Guide

## Quick Reference: Before & After

### 1. Security Headers
```javascript
// ❌ BEFORE: No security headers
const express = require('express');
const app = express();

// ✅ AFTER: Add Helmet
const helmet = require('helmet');
app.use(helmet());
```

### 2. Error Handling
```javascript
// ❌ BEFORE: No error handling
app.get('/users', (req, res) => {
  res.json([{ id: 1, name: 'Alice', email: 'alice@example.com' }]);
});

// ✅ AFTER: With try-catch and proper error response
app.get('/users', (req, res) => {
  try {
    const users = getUsersFromDB();
    res.json(users);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

### 3. Input Validation
```javascript
// ❌ BEFORE: No validation
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ✅ AFTER: Validate query parameters
app.get('/health', (req, res) => {
  // Whitelist allowed parameters
  const allowedParams = new Set(['format']);
  for (const param of Object.keys(req.query)) {
    if (!allowedParams.has(param)) {
      return res.status(400).json({ error: `Invalid parameter: ${param}` });
    }
  }

  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

### 4. Authentication
```javascript
// ❌ BEFORE: No authentication
app.get('/users', (req, res) => {
  res.json([/* all users */]);
});

// ✅ AFTER: Require authentication
const jwt = require('jsonwebtoken');

const authenticateRequest = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Missing authorization token' });
  }

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (error) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

app.get('/users', authenticateRequest, (req, res) => {
  res.json([/* only authenticated users can see this */]);
});
```

### 5. Rate Limiting
```javascript
// ❌ BEFORE: No rate limiting
app.get('/users', (req, res) => { /* ... */ });

// ✅ AFTER: Add rate limiting
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter); // Apply to all routes
```

### 6. CORS Configuration
```javascript
// ❌ BEFORE: No CORS configuration
const app = express();

// ✅ AFTER: Configure CORS explicitly
const cors = require('cors');

app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  methods: ['GET', 'POST'],
  credentials: true,
  optionsSuccessStatus: 200,
  allowedHeaders: ['Content-Type', 'Authorization'],
}));
```

### 7. Request Body Limits
```javascript
// ❌ BEFORE: Unbounded request sizes
app.use(express.json());

// ✅ AFTER: Set reasonable limits
app.use(express.json({ limit: '1kb' }));
app.use(express.urlencoded({ extended: false, limit: '1kb' }));
```

### 8. Safe Binding
```javascript
// ❌ BEFORE: Binds to all interfaces (0.0.0.0)
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// ✅ AFTER: Bind to localhost by default
const HOST = process.env.HOST || 'localhost';
const PORT = process.env.PORT || 3000;

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
});
```

### 9. Environment Configuration
```javascript
// ❌ BEFORE: Hardcoded values
const PORT = 3000;
const DB_URL = 'postgresql://localhost/mydb';

// ✅ AFTER: Use environment variables
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const DB_URL = process.env.DATABASE_URL || 'postgresql://localhost/mydb';
const JWT_SECRET = process.env.JWT_SECRET;

if (!JWT_SECRET) {
  throw new Error('JWT_SECRET environment variable is required');
}
```

### 10. Logging
```javascript
// ❌ BEFORE: Minimal logging
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// ✅ AFTER: Structured logging
const morgan = require('morgan');
const fs = require('fs');

// Request logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Custom error logging
function logError(error, context) {
  const logEntry = {
    timestamp: new Date().toISOString(),
    level: 'error',
    context,
    message: error.message,
    stack: error.stack,
  };
  console.error(JSON.stringify(logEntry));
}
```

### 11. Removing Sensitive Data
```javascript
// ❌ BEFORE: Exposing sensitive information
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ✅ AFTER: Only return necessary fields
app.get('/users', authenticateRequest, (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);

  // Or if user needs email but authenticated:
  // res.json([
  //   { id: 1, name: 'Alice', email: req.user.id === 1 ? 'alice@example.com' : undefined },
  // ]);
});
```

### 12. Global Error Handler
```javascript
// ❌ BEFORE: No centralized error handling
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// Unhandled errors crash the app or leak stack traces

// ✅ AFTER: Add global error handler
app.get('/health', (req, res, next) => {
  try {
    res.json({ status: 'ok' });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Error handler middleware (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(err.status || 500).json({
    error: 'Internal server error',
    ...(isDevelopment && {
      message: err.message,
      stack: err.stack,
    }),
  });
});
```

