export const meta = {
  name: 'app-security-review',
  description: 'Security and error handling review of app.js',
  phases: [
    { title: 'Find Issues', detail: 'Multi-angle security analysis' },
    { title: 'Verify', detail: 'Validate each finding' }
  ]
}

phase('Find Issues')

// Angle 1: Security vulnerabilities and error handling gaps
const securityIssues = await agent(
  `Review this Express.js app.js file for security vulnerabilities and error handling gaps:

const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
