const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '127.0.0.1';

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
});
```

### 6. **No Rate Limiting**
- **Problem**: Any client can hammer the endpoints unlimited times
- **Impact**: DoS attacks, resource exhaustion
- **Fix**: Add rate limiting:
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // Limit each IP to 100 requests per windowMs
});

app.use(limiter);
```

### 7. **Insufficient Logging**
- **Problem**: Only startup message logged; no request/error logging for security audits
- **Impact**: Cannot track abuse, debug issues, or audit access
- **Fix**:
```javascript
