// Secure application with error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ===== SECURITY MIDDLEWARE =====

// 1. Helmet - Sets security-related HTTP headers
app.use(helmet());

// 2. Rate Limiting - Prevent brute force and DDoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 3. Body Parser - Parse JSON with size limits to prevent payload bombs
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: false }));

// ===== INPUT VALIDATION HELPERS =====

const validateIntParam = (value, paramName) => {
  const parsed = parseInt(value, 10);
  if (isNaN(parsed) || parsed < 0) {
    throw new Error(`Invalid ${paramName}: must be a positive integer`);
  }
  return parsed;
};

const validateQueryString = (value, maxLength = 100) => {
  if (!value) return undefined;
  if (typeof value !== 'string') {
    throw new Error('Query parameter must be a string');
  }
  if (value.length > maxLength) {
    throw new Error(`Query parameter exceeds maximum length of ${maxLength}`);
  }
  // Sanitize: remove potentially dangerous characters
  return value.replace(/[<>\"']/g, '');
};

// ===== ROUTES =====

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Health check failed',
    });
  }
});

// Mock user database
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// Get all users with optional filtering
app.get('/users', (req, res) => {
  try {
    // Input validation: Check for unexpected query parameters
    const allowedParams = ['limit', 'search'];
    const queryKeys = Object.keys(req.query);
    const invalidParams = queryKeys.filter(key => !allowedParams.includes(key));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        status: 'error',
        message: `Invalid query parameters: ${invalidParams.join(', ')}`,
      });
    }

    // Validate limit parameter
    let limit = 100; // Default limit
    if (req.query.limit) {
      try {
        limit = validateIntParam(req.query.limit, 'limit');
        if (limit > 1000) {
          limit = 1000; // Cap the limit to prevent resource exhaustion
        }
      } catch (validationError) {
        return res.status(400).json({
          status: 'error',
          message: validationError.message,
        });
      }
    }

    // Validate search parameter
    let filtered = users;
    if (req.query.search) {
      try {
        const searchTerm = validateQueryString(req.query.search, 50);
        const lowerSearch = searchTerm.toLowerCase();
        filtered = users.filter(
          user =>
            user.name.toLowerCase().includes(lowerSearch) ||
            user.email.toLowerCase().includes(lowerSearch)
        );
      } catch (validationError) {
        return res.status(400).json({
          status: 'error',
          message: validationError.message,
        });
      }
    }

    // Apply limit
    const result = filtered.slice(0, limit);

    res.json({
      status: 'success',
      data: result,
      count: result.length,
      total: users.length,
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
      // Never expose stack traces in production
      ...(process.env.NODE_ENV !== 'production' && { details: error.message }),
    });
  }
});

// Get specific user by ID
app.get('/users/:id', (req, res) => {
  try {
    const userId = validateIntParam(req.params.id, 'user ID');
    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        status: 'error',
        message: 'User not found',
      });
    }

    res.json({
      status: 'success',
      data: user,
    });
  } catch (validationError) {
    res.status(400).json({
      status: 'error',
      message: validationError.message,
    });
  } catch (error) {
    console.error('Error in /users/:id endpoint:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});

// ===== ERROR HANDLING =====

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
  });
});

// Global error handler
app.use((err, req, res, next) => {
