const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE - Applied before any routes
// ============================================================================

// 1. Helmet: Set comprehensive HTTP security headers
app.use(helmet());

// 2. Morgan: Request logging for audit trail and monitoring
app.use(morgan('combined'));

// 3. Body parser with size limits to prevent DoS attacks
app.use(express.json({ limit: '1kb' })); // Limit JSON payload to 1KB
app.use(express.urlencoded({ limit: '1kb', extended: false })); // Limit URL-encoded data

// 4. CORS: Explicit origin whitelist (configure based on your needs)
const cors = require('cors');
const allowedOrigins = process.env.ALLOWED_ORIGINS
  ? process.env.ALLOWED_ORIGINS.split(',')
  : ['http://localhost:3000']; // Default for development only

app.use(cors({
  origin: allowedOrigins,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// 5. Rate limiting: Prevent DoS and brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // More restrictive
  skipSuccessfulRequests: true, // Only count failed requests
});

// ============================================================================
// ROUTES WITH INPUT VALIDATION
// ============================================================================

// Health check endpoint - minimal risk but still validated
app.get('/health',
  query('detailed')
    .optional()
    .isIn(['true', 'false'])
    .withMessage('Invalid value for detailed parameter'),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Invalid input',
        details: errors.array()
      });
    }

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString()
    };

    // Include additional details only if requested and valid
    if (req.query.detailed === 'true') {
      response.uptime = process.uptime();
      response.memoryUsage = process.memoryUsage();
    }

    res.json(response);
  }
);

// Users endpoint with input validation
app.get('/users',
  strictLimiter, // Apply stricter rate limiting
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer'),
  query('name')
    .optional()
    .trim()
    .isLength({ min: 1, max: 50 })
    .withMessage('Name must be between 1 and 50 characters'),
  query('email')
    .optional()
    .isEmail()
    .withMessage('Invalid email format'),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Invalid input parameters',
        details: errors.array()
      });
    }

    // Mock user database (in real app, would query actual database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply client-side filters based on validated input
    let filteredUsers = users;

    if (req.query.id) {
      const id = parseInt(req.query.id, 10);
      filteredUsers = filteredUsers.filter(u => u.id === id);
    }

    if (req.query.name) {
      const namePattern = new RegExp(`^${req.query.name}`, 'i'); // Case-insensitive
      filteredUsers = filteredUsers.filter(u => namePattern.test(u.name));
    }

    if (req.query.email) {
      filteredUsers = filteredUsers.filter(u => u.email === req.query.email);
    }

    res.json(filteredUsers);
  }
);

// ============================================================================
// ERROR HANDLING MIDDLEWARE - Applied after all routes
// ============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path
  });
});

// Global error handler - catches all errors and prevents info disclosure
app.use((err, req, res, next) => {
  console.error('Error:', err); // Log full error internally

  // Don't expose stack traces or implementation details to clients
  const statusCode = err.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack }), // Stack trace only in development
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

