process.on('SIGTERM', () => {
  console.log('Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

**Impact:** Prevents information disclosure, cleaner error messages

---

## Problem 4: No Rate Limiting

### ❌ BEFORE
```javascript
// No protection against DoS attacks
// Attacker can: for i in {1..10000}; do curl http://localhost:3000/users & done
// Server crashes due to resource exhaustion
```

### ✅ AFTER
```javascript
const rateLimit = require('express-rate-limit');

// General rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // 100 requests per IP
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Strict limiter for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  skipSuccessfulRequests: true, // Only count failed requests
});

app.use(limiter);
app.get('/users', strictLimiter, ...); // Extra protection
```

**Impact:** Prevents DoS attacks, protects against brute force

---

## Problem 5: Information Disclosure

### ❌ BEFORE
```javascript
// Returns sensitive data without authentication
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// GET /users → 200 OK (Returns emails unprotected)
// GET /users?id=999 → 200 OK (No filtering, returns all data)
```

### ✅ AFTER (Example Authentication Pattern)
```javascript
// In real implementation:
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // Verify JWT/session...
  next();
};

app.get('/users', authenticate, strictLimiter, 
  query('id').optional().isInt({ min: 1 }),
  (req, res) => {
    // Only authenticated users can access
    // Only their own data or admin data
  }
);

// GET /users → 401 Unauthorized
// GET /users -H "Authorization: Bearer <token>" → 200 OK (only if valid token)
```

**Impact:** Prevents unauthorized access to sensitive data

---

## Problem 6: No Body Size Limits

### ❌ BEFORE
```javascript
const express = require('express');
const app = express();
// No body parser configuration
// Attacker sends 1GB payload → Memory exhaustion → Crash
```

### ✅ AFTER
```javascript
app.use(express.json({ limit: '1kb' }));           // Limit JSON to 1KB
app.use(express.urlencoded({ 
  limit: '1kb',                                     // Limit URL-encoded to 1KB
  extended: false 
}));

// POST /users with 10MB body → 413 Payload Too Large
```

**Impact:** Prevents memory exhaustion attacks

---

## Quick Comparison Table

| Security Issue | Before | After | Impact |
|---|---|---|---|
| **HTTP Headers** | ❌ None | ✅ Helmet | Prevents clickjacking, MIME sniffing |
| **Input Validation** | ❌ None | ✅ express-validator | Prevents injection attacks |
| **Rate Limiting** | ❌ None | ✅ express-rate-limit | Prevents DoS attacks |
| **CORS** | ❌ Allow all | ✅ Whitelist | Prevents cross-origin attacks |
| **Body Size Limits** | ❌ Unlimited | ✅ 1KB limit | Prevents memory exhaustion |
| **Request Logging** | ❌ None | ✅ Morgan | Enables monitoring/audit |
| **Error Handling** | ❌ Stack traces exposed | ✅ Sanitized errors | Prevents info disclosure |
| **Authentication** | ❌ None | ✅ Example shown | Prevents unauthorized access |
| **Request Timeout** | ❌ None | ✅ 30s timeout | Prevents resource exhaustion |
| **Graceful Shutdown** | ❌ None | ✅ SIGTERM handler | Clean server shutdown |

---

## Deployment Checklist

- [ ] Install dependencies: `npm install helmet express-rate-limit express-validator cors morgan`
- [ ] Replace `app.js` with `app-improved.js` (or apply changes incrementally)
- [ ] Configure environment variables:
  - `PORT` - Server port (default: 3000)
  - `NODE_ENV` - Environment (development/production)
  - `ALLOWED_ORIGINS` - Comma-separated list of allowed CORS origins
- [ ] Enable HTTPS in production (use reverse proxy or SSL certificates)
- [ ] Set up monitoring and alerting for rate limit hits
- [ ] Test all endpoints with invalid inputs
- [ ] Run security scan with OWASP ZAP or Burp Suite
- [ ] Review logs for suspicious patterns
- [ ] Document API authentication/authorization flow
- [ ] Set up incident response procedures

---

## Testing Commands

```bash
