app.use((req, res, next) => {
  const origin = req.get('origin');
  if (corsOrigins.includes(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
  }
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});
```

**Finding 2**: CORS headers (Allow-Methods and Allow-Headers) are set for ALL requests, even when the origin validation FAILS. Only Allow-Origin is conditional. Is this a real security vulnerability that leaks API capabilities?

**Finding 3**: If CORS_ORIGINS='http://example.com, http://evil.com' (with trailing space), the split creates entries with spaces like ' http://evil.com' that won't match. Real issue?

---

```javascript
// Line 71-93: /users endpoint
app.get('/users', (req, res) => {
  try {
    // Input validation
    if (req.query.limit) {
      const limit = parseInt(req.query.limit, 10);
      if (isNaN(limit) || limit < 1 || limit > 1000) {
        return res.status(400).json({
