  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint (protected)
app.get('/users', authenticate, query('limit').optional().isInt().toInt(), (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const limit = req.query.limit || 100;
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ].slice(0, limit));
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Error handler (must be last)
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(err.status || 500).json({ 
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message 
  });
});

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
});

module.exports = app;
```

### **Additional Recommendations**

- **Add `.env.example`** with safe defaults for configuration
- **Implement proper authentication** (JWT, OAuth2, etc.)
- **Add unit tests** for error paths
- **Use HTTPS** in production (add enforcement)
- **Implement request validation schema** using a library like `joi`
- **Add monitoring and alerting** for security events
- **Scan dependencies** regularly with `npm audit`

