// Secure Express application with error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const validator = require('validator');

const app = express();

// ============================================
// 1. SECURITY MIDDLEWARE
// ============================================

// Add security headers
app.use(helmet());

// Request logging (audit trail)
app.use(morgan('combined'));

// Parse JSON with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting - prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// ============================================
// 2. INPUT VALIDATION MIDDLEWARE
// ============================================

const validateQuery = (req, res, next) => {
  const { limit, offset } = req.query;

  // Validate numeric parameters
  if (limit !== undefined) {
    const parsedLimit = parseInt(limit, 10);
    if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 1000) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be a number between 1 and 1000.',
      });
    }
  }

  if (offset !== undefined) {
    const parsedOffset = parseInt(offset, 10);
    if (isNaN(parsedOffset) || parsedOffset < 0) {
      return res.status(400).json({
        error: 'Invalid offset parameter. Must be a non-negative number.',
      });
    }
  }

  next();
};

// ============================================
// 3. ERROR HANDLING MIDDLEWARE
// ============================================

// Global error handler
const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    method: req.method,
    url: req.url,
    ip: req.ip,
  });

  // Don't expose internal error details to client
  const statusCode = err.statusCode || 500;
  const message = statusCode === 500 ? 'Internal Server Error' : err.message;

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { details: err.message }),
  });
};

// ============================================
// 4. ENDPOINTS WITH VALIDATION & ERROR HANDLING
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (err) {
    errorHandler(err, req, res);
  }
});

// Users endpoint with validation and auth
app.get('/users', validateQuery, (req, res) => {
  try {
    // Example: Check for authorization header (implement real auth logic)
    const authHeader = req.get('Authorization');
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({
        error: 'Unauthorized. Please provide a valid Bearer token.',
      });
    }

    // Pagination parameters with defaults
    const limit = Math.min(parseInt(req.query.limit || 10, 10), 100);
    const offset = Math.max(parseInt(req.query.offset || 0, 10), 0);

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length,
      },
    });
  } catch (err) {
    errorHandler(err, req, res);
  }
});

// Example POST endpoint with input validation
app.post('/users', express.json(), (req, res) => {
  try {
    const { name, email } = req.body;

    // Input validation
    if (!name || typeof name !== 'string') {
      return res.status(400).json({
        error: 'Missing or invalid "name" field. Must be a non-empty string.',
      });
    }

    if (!email || !validator.isEmail(email)) {
      return res.status(400).json({
        error: 'Missing or invalid "email" field. Must be a valid email address.',
      });
    }

    // Sanitize inputs
    const sanitizedName = validator.escape(name.trim());
    const sanitizedEmail = validator.normalizeEmail(email);

    // In a real app, save to database with parameterized queries
    res.status(201).json({
      id: 3,
      name: sanitizedName,
      email: sanitizedEmail,
    });
  } catch (err) {
    errorHandler(err, req, res);
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
  });
});

// Global error handler (must be last)
app.use(errorHandler);

// ============================================
// 5. SERVER STARTUP WITH ERROR HANDLING
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled errors
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

