export const meta = {
  name: 'review-app-js',
  description: 'Multi-angle security and correctness review of app.js',
  phases: [
    { title: 'Find Issues', detail: 'Run 7 independent finders across correctness, security, and best practices' },
    { title: 'Verify', detail: 'Verify top candidates with concrete failure scenarios' },
  ],
}

const app_js = `// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;`

phase('Find Issues')

// Angle A: Line-by-line correctness
const correctness_a = await agent('Review this Express app line-by-line for correctness bugs: missing error handling, null/undefined deref, wrong conditions, timing issues. Code:\n\n' + app_js, {
  label: 'correctness:line-by-line',
  schema: {
    type: 'object',
    properties: {
      findings: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            line: { type: 'number' },
            summary: { type: 'string' },
            failure_scenario: { type: 'string' },
          },
        },
      },
    },
  },
})

// Angle B: Security vulnerabilities
const security_b = await agent('Audit this Express app for security vulnerabilities: input validation, data exposure, injection attacks, missing headers, hardcoded ports, sensitive data in logs, CORS/auth gaps. Code:\n\n' + app_js, {
  label: 'security:vulnerabilities',
  schema: {
    type: 'object',
    properties: {
      findings: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            line: { type: 'number' },
            summary: { type: 'string' },
            failure_scenario: { type: 'string' },
          },
        },
      },
    },
  },
})

// Angle C: Error handling and resilience
