  label: 'error:handling',
  schema: {
    type: 'object',
    properties: {
      findings: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            line: { type: 'number' },
            summary: { type: 'string' },
            failure_scenario: { type: 'string' },
          },
        },
      },
