// Simple application with security hardening
// Enhanced error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const app = express();

// ===== Security Middleware =====

// Use helmet for security headers
app.use(helmet());

// Request logging
app.use(morgan('combined'));

// Limit request body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// ===== Routes with Error Handling and Validation =====

app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.get('/users', (req, res) => {
  try {
    // Input validation for query parameters
    const limit = parseInt(req.query.limit, 10) || 10;
    const offset = parseInt(req.query.offset, 10) || 0;

    // Validate input ranges
    if (limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Validation error',
        details: 'limit must be between 1 and 100'
      });
    }

    if (offset < 0) {
      return res.status(400).json({
        error: 'Validation error',
        details: 'offset must be >= 0'
      });
    }

    // Mock data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    // Return only safe fields (no passwords, sensitive data)
    const safeUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      email: user.email
    }));

    res.json({
      data: safeUsers,
      pagination: {
        limit,
        offset,
        total: allUsers.length
      }
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error',
