const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const expressJwt = require('express-jwt');
const jwt = require('jsonwebtoken');
const { query, validationResult, param } = require('express-validator');
const winston = require('winston');
const expressRequestId = require('express-request-id')();
const slowDown = require('express-slow-down');

const app = express();

// ============= CONFIGURATION =============
const SECRET = process.env.JWT_SECRET || 'change-this-in-production';
const isDevelopment = process.env.NODE_ENV === 'development';

// ============= LOGGING (Issue #7) =============
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'api' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    process.env.NODE_ENV !== 'test' && new winston.transports.Console({
      format: winston.format.simple()
    })
  ].filter(Boolean)
});

// ============= SECURITY HEADERS (Issue #1) =============
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  },
}));
app.use(helmet.hsts({ maxAge: 31536000, includeSubDomains: true, preload: true }));
app.use(helmet.frameguard({ action: 'deny' }));

// ============= REQUEST SIZE & TIMEOUT LIMITS (Issue #8) =============
app.use(express.json({ limit: '10kb', strict: true }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

app.use((req, res, next) => {
  req.setTimeout(30000);
  res.setTimeout(30000);
  next();
});

// ============= REQUEST ID & LOGGING (Issue #7) =============
app.use(expressRequestId);

app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    const logLevel = res.statusCode >= 500 ? 'error' : res.statusCode >= 400 ? 'warn' : 'info';
    logger[logLevel]({
      requestId: req.id,
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      timestamp: new Date().toISOString()
    });
  });
  next();
});

// ============= RATE LIMITING (Issue #4) =============
