});

// ============= PROTECTED ENDPOINTS =============
// Input validation middleware (Issue #2)
const validateUserQuery = [
  query('id').optional().isInt({ min: 1 }).toInt(),
  query('role').optional().isIn(['admin', 'user']),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
