        event: 'validation_error',
        errors: errors.array(),
        requestId: req.id,
        ip: req.ip
      });
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  }
];

app.get('/users', authMiddleware, validateUserQuery, (req, res) => {
