    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ============= 404 HANDLER (Issue #6) =============
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist',
    requestId: req.id
  });
});

// ============= GLOBAL ERROR HANDLER (Issue #6) =============
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || err.status || 500;

  logger.error({
    event: 'error',
    message: err.message,
    stack: isDevelopment ? err.stack : undefined,
    path: req.path,
    method: req.method,
    requestId: req.id,
    statusCode
  });

