// Test cases to validate the input handling

// Simulate the validation logic from app.js
function validateParams(limitStr, offsetStr) {
  const limit = parseInt(limitStr, 10) || 10;
  const offset = parseInt(offsetStr, 10) || 0;

  console.log(`Input: limit="${limitStr}", offset="${offsetStr}"`);
  console.log(`After parseInt: limit=${limit}, offset=${offset}`);
  console.log(`Number.isInteger(limit): ${Number.isInteger(limit)}, Number.isInteger(offset): ${Number.isInteger(offset)}`);

  // Validation checks from code
  if (!Number.isInteger(limit) || !Number.isInteger(offset)) {
    console.log("FAIL: Not integers\n");
    return null;
  }

  if (limit < 1 || limit > 100) {
    console.log("FAIL: Limit out of range\n");
    return null;
  }

  if (offset < 0) {
    console.log("FAIL: Negative offset\n");
    return null;
  }

  console.log("PASS\n");
  return { limit, offset };
}

// Test cases
console.log("=== POTENTIAL VULNERABILITIES ===\n");

console.log("1. Infinity values:");
validateParams("Infinity", "0");
validateParams("Infinity", "Infinity");

console.log("2. NaN edge cases:");
validateParams("NaN", "0");
validateParams("", "");

console.log("3. Floating point values:");
validateParams("10.5", "5.9");
validateParams("10.9", "0");

console.log("4. Negative values:");
validateParams("-100", "-5");

console.log("5. Very large numbers:");
validateParams("999999999", "999999999");
validateParams("9007199254740992", "0"); // MAX_SAFE_INTEGER + 1

console.log("6. Scientific notation:");
validateParams("1e10", "0");
validateParams("1e-10", "0");

console.log("7. Hex/Octal notation:");
validateParams("0xFF", "0");
validateParams("0o77", "0");

console.log("8. Whitespace and padding:");
validateParams(" 10 ", " 5 ");
validateParams("010", "010"); // Leading zeros

console.log("9. Special strings:");
validateParams("Infinity", "undefined");
validateParams("null", "null");

console.log("10. Combined bypass attempts:");
validateParams("101", "0");
validateParams("1", "-1");
