// Improved application with security best practices
// Error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');

const app = express();

// Environment setup
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============ SECURITY MIDDLEWARE ============

// Set security HTTP headers
app.use(helmet());

// Sanitize data against NoSQL injection attacks
app.use(mongoSanitize());

// Sanitize data against XSS attacks
app.use(xss());

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Body parser with size limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============ REQUEST LOGGING ============

app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path}`);
  next();
});

// ============ ROUTES ============

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV,
    });
  } catch (error) {
    console.error('Error in /health endpoint:', error);
    res.status(500).json({ status: 'error', message: 'Internal server error' });
  }
});

// Get users endpoint with improved security
app.get('/users', (req, res) => {
  try {
    // Validate query parameters (if using pagination)
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;

    // Input validation
    if (page < 1 || limit < 1 || limit > 100) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid pagination parameters. Limit must be between 1-100.',
      });
    }

    // In production: add authentication check
    // if (!req.headers.authorization) {
    //   return res.status(401).json({ status: 'error', message: 'Unauthorized' });
    // }

    // Sanitize response - don't expose sensitive data
    const users = [
      { id: 1, name: 'Alice' }, // removed email
      { id: 2, name: 'Bob' },   // removed email
    ];

    res.status(200).json({
      status: 'success',
      data: users,
      pagination: { page, limit, total: users.length },
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      status: 'error',
      message: NODE_ENV === 'development' ? error.message : 'Internal server error',
    });
  }
});

// ============ ERROR HANDLING ============

// 404 handler - must be after all other routes
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Route not found',
    path: req.path,
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: NODE_ENV === 'development' ? err.stack : undefined,
    url: req.originalUrl,
    method: req.method,
  });

  // Default error response
  const statusCode = err.statusCode || 500;
  const message = NODE_ENV === 'development' ? err.message : 'Internal server error';

  res.status(statusCode).json({
    status: 'error',
    message,
    ...(NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ============ SERVER STARTUP ============

const server = app.listen(PORT, () => {
  console.log(`✓ Server running on port ${PORT} (${NODE_ENV})`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review: app.js

## Executive Summary

The current `app.js` has **7 critical security and error handling gaps** that should be addressed before production use.

---

## 🔴 Critical Issues

### 1. **No Error Handling**

**Problem:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

- No error handler for failed startup
- Route handlers have no try-catch blocks
- Unhandled rejections will crash the server silently
- No 404 or 500 error responses

**Fix:**
```javascript
// Add error handlers
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({ error: 'Internal server error' });
});

// Add process error handlers
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  process.exit(1);
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});
```

---

### 2. **No Input Validation**

**Problem:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // No validation of query params
});
```

- No query parameter validation
- Attackers could send malicious payloads
- No request size limits
- No validation of data types

**Fix:**
```javascript
// Use middleware like joi, yup, or express-validator
const { query, validationResult } = require('express-validator');

app.get('/users',
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Process validated input
  }
);

// Add body size limits
app.use(express.json({ limit: '10kb' }));
```

---

### 3. **Data Exposure (Sensitive Information)**

**Problem:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' }, // Email exposed!
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

- Email addresses exposed to anyone
- No authentication required
- Violates least-privilege principle

**Fix:**
```javascript
// Add authentication middleware
const requireAuth = (req, res, next) => {
  if (!req.headers.authorization) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // Verify token
  next();
};

app.get('/users', requireAuth, (req, res) => {
  // Only return non-sensitive fields
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});
```

---

### 4. **Missing Security Headers**

**Problem:**
- No CORS configuration (vulnerable to CSRF)
- No rate limiting (vulnerable to DoS attacks)
- No XSS/injection protections
- No HTTP security headers

**Fix:**
```javascript
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

// Add security headers
app.use(helmet());

// Add rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 100, // requests per windowMs
});
app.use(limiter);

// Configure CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
}));
```

---

### 5. **Hardcoded Configuration**

**Problem:**
```javascript
app.listen(3000, () => { // Port hardcoded
  console.log('Server running on port 3000');
});
```

- Port is hardcoded
- No environment awareness
- Can't change config without modifying code

**Fix:**
```javascript
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV})`);
});
```

---

## 🟡 Medium Priority Issues

### 6. **No Input Sanitization**

**Risk:** NoSQL Injection, XSS attacks

```javascript
// Add middleware
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');

app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(xss());           // Prevent XSS attacks
```

---

### 7. **Insufficient Logging**

**Problem:**
- Can't track errors or security events
- No audit trail
- Hard to debug production issues

**Fix:**
```javascript
// Add request logging
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// Log errors
app.use((err, req, res, next) => {
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    path: req.path,
    method: req.method,
    stack: err.stack,
  });
  res.status(500).json({ error: 'Internal server error' });
});
```

